/* =========================================================
   NHIỆM VỤ TUẦN của từng lớp (hiện ở Góc lớp). Ghi id học liệu ở trên.
   ========================================================= */
const NHIEM_VU = Object.assign({ tuan: '' }, CH.nv);   // bản đồng nghiệp: lấy từ máy chủ của thầy cô
/* Bài ĐÃ GIAO ở các tuần trước (giữ lại khi đổi nhiệm vụ tuần mới).
   Trang cô tính «% hoàn thành theo chương» trên: bài đã giao tuần trước + nhiệm vụ tuần này.
   Đổi tuần: chép id của tuần cũ vào đây rồi mới sửa NHIEM_VU. */
const GIAO_TRUOC = CH.gt || {};
/* NHIỆM VỤ TUẦN SAU — tự đổi lúc «tu» (sếp giao 24/11/2026): tới giờ, nhiệm vụ tuần cũ chuyển vào GIAO_TRUOC, nhiệm vụ dưới đây thành tuần hiện tại.
   10A2, 10A3: Bài 13, 14 · 10A4: Bài 11. Đổi tuần tiếp theo: chép tay theo cách cũ (tuần cũ vào GIAO_TRUOC, sửa NHIEM_VU) rồi xoá khối này. */
const NHIEM_VU_TUAN_SAU = {
  tu: '2026-11-30T00:00:00+07:00',
  tuan: '30/11 – 06/12/2026 · làm lần lượt từ trên xuống, theo lời cô dặn từng tiết',
  '10A2': ['bai13-elearning-lien-ket-hydrogen', 'cd-b13-t1', 'bai14-elearning-on-tap-chuong-3', 'cd-b14', 'bai13-luyen-dang', 'bai14-luyen-dang'],
  '10A3': ['bai13-elearning-lien-ket-hydrogen', 'cd-b13-t1', 'bai14-elearning-on-tap-chuong-3', 'cd-b14', 'bai13-luyen-dang', 'bai14-luyen-dang'],
  '10A4': ['bai11-elearning-lien-ket-ion', 'cd-b11-t1', 'bai11-luyen-dang'],
};
(function () {
  if (typeof CH !== 'undefined' || Date.now() < Date.parse(NHIEM_VU_TUAN_SAU.tu)) return;   // bản đồng nghiệp (CH) không dùng khối này
  Object.keys(NHIEM_VU_TUAN_SAU).filter(l => l !== 'tu' && l !== 'tuan').forEach(l => {
    GIAO_TRUOC[l] = [...new Set((GIAO_TRUOC[l] || []).concat(NHIEM_VU[l] || []))];
    NHIEM_VU[l] = NHIEM_VU_TUAN_SAU[l].slice();
  });
  NHIEM_VU.tuan = NHIEM_VU_TUAN_SAU.tuan;
})();
